section.content:
ALGORITHME Inverse ;

VAR nombre : Réel ;

DÉBUT

  ÉCRIRE('Donner un nombre : ');

  LIRE(nombre) ;

  ÉCRIRE('L'inverse du nombre : ', nombre, 'est : ', 1/nombre) ;

FIN.

subsection.content:
SI (condition) ALORS

  Traitement ;

FIN SI ;

En langage C :

if (condition)

{

  Traitement ;

}

ALGORITHME valeur_absolue ;

VAR Nombre : Entier ;

DÉBUT

  LIRE(nombre) ;

  SI (nombre < 0) ALORS

    nombre <- -(nombre) ;

  FIN SI ;

  ÉCRIRE('La valeur absolue est ', nombre) ;

FIN.

ALGORITHME InverseComplet ;

VAR nombre : Réel ;

DÉBUT

  ÉCRIRE('Donner un nombre ') ;

  LIRE(nombre) ;

  SI (nombre <> 0) ALORS

    ÉCRIRE('L'inverse du nombre : ', nombre, ' est : ', 1/nombre) ;

  FIN SI ;

  SI (nombre = 0) ALORS

    ÉCRIRE('Le nombre tapé est nul') ;

  FIN SI ;

FIN.

SI (condition) ALORS

  Traitement 1 ;

SINON

  Traitement 2 ;

FIN SI ;

En langage C :

if (condition)

{

  Traitement 1 ;

}

else

{

  Traitement 2 ;

}

ALGORITHME InverseAltComp ;

VAR nombre : Réel ;

DÉBUT

  LIRE(nombre) ;

  SI (nombre <> 0) ALORS

    ÉCRIRE('L'inverse du nombre : ', nombre, ' est : ', 1/nombre) ;

  SINON

    ÉCRIRE('Le nombre introduit est nul') ;

  FIN SI ;

FIN.

ALGORITHME Observation ;

VAR Moyenne : Réel ;

DÉBUT

  LIRE(Moyenne) ;

  SI (Moyenne >= 10) ALORS

    ÉCRIRE('Admis') ;

  SINON

    SI (Moyenne >= 9.5) ALORS

      ÉCRIRE('Racheté') ;

    SINON

      ÉCRIRE('Ajourné') ;

    FIN SI ;

  FIN SI ;

FIN.

SELON (expression) FAIRE

  CAS C1 : Traitement 1 ;

  CAS C2 : Traitement 2 ;

  CAS C3 : Traitement 3 ;

  ...

  CAS CN : Traitement N ;

  CAS AUTRE Traitement (N+1) ;

FIN SELON ;

En langage C :

switch (expression)

{

  case C1 : Traitement 1 ; break ;

  case C2 : Traitement 2 ; break ;

  ...

  default : Traitement (N+1) ;

}

ALGORITHME jours_mois ;

VAR mois : Entier ;

DÉBUT

  ÉCRIRE('De quel mois s'agit-il ?');

  LIRE(mois) ;

  SELON (mois) FAIRE

    CAS 1, 3, 5, 7, 8, 10, 12 : ÉCRIRE('Nombre de jours : 31') ;

    CAS 4, 6, 9, 11 : ÉCRIRE('Nombre de jours : 30') ;

    CAS 2 : ÉCRIRE('Nombre de jours : 28 ou 29') ;

    CAS AUTRE : ÉCRIRE('Ce mois n'existe pas') ;

  FIN SELON ;

FIN.

ALGORITHME Alg1 ;

VAR X, Y : Entier ;

DÉBUT

  X <- 3 ;

  Y <- 2 ;

  SI (X<Y) ALORS

    ÉCRIRE(Y, ' est supérieur à', X) ;

  SINON

    SI (Y > 0) ALORS

      ÉCRIRE(Y, ' est strictement positif') ;

    SINON

      ÉCRIRE(Y, ' est inférieur ou égal à 0') ;

    FIN SI ;

  FIN SI ;

FIN.

ALGORITHME Alg2 ;

VAR X, Y : Entier ;

DÉBUT

  X <- 3 ;

  Y <- 2 ;

  SELON (X+Y-1) FAIRE

    CAS 3 : ÉCRIRE('Premier CAS') ;

    CAS 5 : ÉCRIRE('Deuxième CAS') ;

    CAS 7 : ÉCRIRE('Troisième CAS') ;

    CAS AUTRE : ÉCRIRE('CAS AUTRE') ;

  FIN SELON ;

FIN.
